/** Explicit read adapter tests, no live inventory/clinical/SQL/HTTP evidence; writes remain legacy. */
class InventoryServiceSqlServerTest {
 final Fixture f=new Fixture();final Sql sql=mock(Sql.class);final Access access=mock(Access.class);final InventoryService service=new InventoryService(f.store,sql,access);
 InventoryServiceSqlServerTest(){actor("AUD");}
 void actor(String role){f.actor(role);doReturn(f.actor).when(access).actor();TraceContext.REQUEST.set(f.request);}
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 @Test void exactReadRolesModulesAndSingleSpWithoutBranchesOrLegacySql(){for(String role:List.of("ALM","FAR","AUD")){actor(role);assertEquals(List.of(),service.lots());}for(String role:List.of("ALM","AUD")){actor(role);assertEquals(List.of(),service.transfers());}for(String role:List.of("FAR","PRO","AUD")){actor(role);assertEquals(List.of(),service.prescriptions());}verify(access,times(3)).roles("ALM","FAR","AUD");verify(access,times(2)).roles("ALM","AUD");verify(access,times(3)).roles("FAR","PRO","AUD");verify(access,times(5)).module("INVENTORY");verify(access,times(3)).module("PHARMACY");verify(access,never()).branch(anyString());verify(access,never()).write(anyString(),any(String[].class));assertEquals(8,f.calls.size());verifyNoInteractions(sql);}
 @Test void prescriptionsFarWithoutProDependencyAndTenantWideShapes(){actor("FAR");f.lots.add(lot());f.prescriptions.add(prescription());assertEquals(8,((Map<?,?>)((List<?>)service.lots()).getFirst()).size());assertEquals(6,((Map<?,?>)((List<?>)service.prescriptions()).getFirst()).size());actor("ALM");f.transfers.add(transfer());assertEquals(10,((Map<?,?>)((List<?>)service.transfers()).getFirst()).size());verify(access,never()).branch(anyString());verifyNoInteractions(sql);}
 @Test void rolesAreSpecificNoPlatformAndNoExtraProGate(){actor("PRO");assertEquals(403,assertThrows(ApiException.class,service::lots).status);assertEquals(403,assertThrows(ApiException.class,service::transfers).status);actor("ALM");assertEquals(403,assertThrows(ApiException.class,service::prescriptions).status);actor("FAR");assertEquals(403,assertThrows(ApiException.class,service::transfers).status);for(String role:List.of("ADM","REC","CAJ","PAC","RES","SAD","SOP")){actor(role);assertEquals(403,assertThrows(ApiException.class,service::lots).status);assertEquals(403,assertThrows(ApiException.class,service::prescriptions).status);}verifyNoInteractions(f.executor,sql);}
 @Test void missingRequest401HostAndActorDiscordanceStopBeforeSp(){TraceContext.REQUEST.remove();assertEquals(500,assertThrows(ApiException.class,service::lots).status);actor("AUD");doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,service::transfers).status);actor("AUD");f.request.removeAttribute("health.actor");f.request.addHeader("X-Roles","AUD");assertEquals(403,assertThrows(ApiException.class,service::prescriptions).status);actor("AUD");f.request.setAttribute("health.tenant","bad");assertEquals(500,assertThrows(ApiException.class,service::lots).status);actor("AUD");f.request.setAttribute("health.tenant",new TenantRef(OTHER,"Foreign","foreign","CLINIC","HUMAN","ACTIVE",List.of("INVENTORY")));assertEquals(403,assertThrows(ApiException.class,service::transfers).status);verifyNoInteractions(f.executor,sql);}
 @Test void moduleAndRoleGateBeforeStoreAndReadNoStatusWriteGate(){doThrow(ApiException.forbidden()).when(access).roles("ALM","FAR","AUD");assertEquals(403,assertThrows(ApiException.class,service::lots).status);verify(access,never()).module(anyString());doNothing().when(access).roles("ALM","FAR","AUD");doThrow(new ApiException(403,"MODULE_NOT_INCLUDED","Safe")).when(access).module("INVENTORY");assertEquals("MODULE_NOT_INCLUDED",assertThrows(ApiException.class,service::lots).code);verifyNoInteractions(f.executor,sql);}
 @Test void safeSpAndCommitFailuresDoNotUseLegacyOrFakeEmpty(){doThrow(new RuntimeException(new java.sql.SQLException("private driver canary",null,51001))).when(f.executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,service::prescriptions);assertEquals(403,e.status);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));verify(f.executor).execute(eq(SqlServerProcedure.INVENTORY_PRESCRIPTIONS),any());verifyNoInteractions(sql);}
 @Test void joinCommitAndMalformedDataRollBackModelWithoutPartialRead(){f.lots.add(lot());f.manager.failCommit=true;assertEquals(500,assertThrows(ApiException.class,service::lots).status);f.lots.getFirst().put("quantity","bad");assertEquals(500,assertThrows(ApiException.class,service::lots).status);assertEquals("rollback",f.manager.events.getLast());f.lots.clear();assertThrows(RuntimeException.class,()->f.manager.outer(()->{service.lots();throw new RuntimeException("cancel");}));assertEquals("rollback",f.manager.events.getLast());verifyNoInteractions(sql);}
 @Test void mixedConstructorUsesTransferReceiveSpWithoutBranchOrLegacySql(){actor("ALM");assertEquals(10,((Map<?,?>)service.transfer(transferInput(new BigDecimal("0.001")),"synthetic-key-001")).size());assertEquals("RECEIVED",((Map<?,?>)service.receive(ID)).get("status"));verify(access,times(2)).write("INVENTORY","ALM");verify(access,never()).branch(anyString());assertEquals(List.of(SqlServerProcedure.INVENTORY_TRANSFER_START,SqlServerProcedure.INVENTORY_TRANSFER_RECEIVE),f.calls);verifyNoInteractions(sql);}
 @Test void minimalSpringSelectsLegacyReadConstructorWithoutDatasource(){when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());when(access.tenantId()).thenReturn(TENANT);try(var context=new AnnotationConfigApplicationContext()){context.registerBean(Sql.class,()->sql);context.registerBean(Access.class,()->access);context.registerBean(InventoryService.class);context.refresh();var legacy=context.getBean(InventoryService.class);assertEquals(List.of(),legacy.lots());assertEquals(List.of(),legacy.transfers());assertEquals(List.of(),legacy.prescriptions());verify(sql,times(3)).rows(anyString(),eq(TENANT));assertEquals(0,context.getBeanNamesForType(SqlServerInventoryStore.class).length);assertEquals(0,context.getBeanNamesForType(javax.sql.DataSource.class).length);}verifyNoInteractions(f.executor);}
 @Test void lotAndReceiveUseOnlyTheirOwnSpAndNoAccessBranchOrSql(){actor("ALM");var lot=(Map<?,?>)service.lot(lotInput());assertEquals(8,lot.size());assertEquals(0,((BigDecimal)lot.get("quantity")).signum());var move=(Map<?,?>)service.move(moveInput("RECEIVE",new BigDecimal("0.001")),"synthetic-key-001");assertEquals(11,move.size());verify(access,times(2)).write("INVENTORY","ALM");verify(access,never()).branch(anyString());assertEquals(List.of(SqlServerProcedure.INVENTORY_LOT_CREATE,SqlServerProcedure.INVENTORY_MOVE),f.calls);verifyNoInteractions(sql);}
 @Test void dispenseRequiresFarAndKeepsMissingPrescriptionMessageWithoutQueries(){actor("FAR");var e=assertThrows(ApiException.class,()->service.move(new Move(OTHER,"DISPENSE",BigDecimal.ONE,OTHER,null),"synthetic-key-001"));assertEquals(400,e.status);assertEquals("Selecciona la prescripci\u00f3n a dispensar.",e.getMessage());verifyNoInteractions(f.executor,sql);var output=(Map<?,?>)service.move(moveInput("DISPENSE",new BigDecimal("0.001")),"synthetic-key-001");assertEquals(OTHER,output.get("prescriptionId"));verify(access,times(2)).write("INVENTORY","FAR");verify(access,never()).branch(anyString());assertEquals(List.of(SqlServerProcedure.INVENTORY_MOVE),f.calls);}
 @Test void writeRoleMatrixAndHostDiscordanceNeverReachPersistence(){for(String role:List.of("AUD","PRO","ALM","FAR","SAD","SOP")){actor(role);if(!role.equals("ALM"))assertEquals(403,assertThrows(ApiException.class,()->service.lot(lotInput())).status);if(!role.equals("FAR"))assertEquals(403,assertThrows(ApiException.class,()->service.move(moveInput("DISPENSE",BigDecimal.ONE),"synthetic-key-001")).status);}actor("ALM");f.request.setAttribute("health.actor","forged");assertEquals(403,assertThrows(ApiException.class,()->service.lot(lotInput())).status);actor("ALM");f.request.setAttribute("health.tenant","bad");assertEquals(500,assertThrows(ApiException.class,()->service.move(moveInput("RECEIVE",BigDecimal.ONE),"synthetic-key-001")).status);TraceContext.REQUEST.remove();assertEquals(500,assertThrows(ApiException.class,()->service.lot(lotInput())).status);verifyNoInteractions(f.executor,sql);}
 @Test void accessWriteGatePrecedesDtoValidationAndRejectsBeforeSp(){actor("ALM");doThrow(new ApiException(403,"SUSPENDED","Safe")).when(access).write("INVENTORY","ALM");assertEquals("SUSPENDED",assertThrows(ApiException.class,()->service.lot(null)).code);assertEquals("SUSPENDED",assertThrows(ApiException.class,()->service.move(null,null)).code);verify(access,never()).branch(anyString());verifyNoInteractions(f.executor,sql);}
 @Test void validReplayReturnsExistingIdActorAndConflictNeverRetries(){actor("ALM");var p=moveInput("RECEIVE",new BigDecimal("0.001"));var old=movement();old.put("actorId",OTHER);old.put("requestHash",Checks.hash(f.mapper.writeValueAsString(p)));f.results.add(new SqlServerExecutor.Result(List.of(List.of(old)),List.of()));var output=(Map<?,?>)service.move(p,"synthetic-key-001");assertEquals(ID,output.get("id"));assertEquals(OTHER,output.get("actorId"));doThrow(new RuntimeException(new java.sql.SQLException("private stock conflict canary",null,51003))).when(f.executor).execute(eq(SqlServerProcedure.INVENTORY_MOVE),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->service.move(p,"synthetic-key-001"));assertEquals(409,e.status);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));verify(f.executor,times(2)).execute(eq(SqlServerProcedure.INVENTORY_MOVE),any(),any(Object[].class));verifyNoInteractions(sql);}
 @Test void writeMappingCommitAndOuterCancellationLeaveNoPartialSuccess(){actor("ALM");f.results.add(new SqlServerExecutor.Result(List.of(List.of(lot())),List.of()));assertEquals(500,assertThrows(ApiException.class,()->service.lot(lotInput())).status);assertEquals("rollback",f.manager.events.getLast());f.manager.failCommit=true;assertEquals(500,assertThrows(ApiException.class,()->service.move(moveInput("RECEIVE",BigDecimal.ONE),"synthetic-key-001")).status);assertThrows(RuntimeException.class,()->f.manager.outer(()->{service.lot(lotInput());throw new RuntimeException("cancel");}));assertEquals("rollback",f.manager.events.getLast());assertSame(f.actor,f.request.getAttribute("health.actor"));verifyNoInteractions(sql);}

 @Test void explicitLegacyConstructorKeepsOriginalTransferReceiveSqlBodies(){actor("ALM");var legacy=new InventoryService(sql,access);when(access.tenantId()).thenReturn(TENANT);when(access.userId()).thenReturn(ACTOR);when(sql.json(any())).thenReturn("{}");when(sql.one(anyString(),any(Object[].class))).thenReturn(Map.of("id",ID,"branchId",OTHER,"destinationBranchId",OTHER));legacy.transfer(transferInput(new BigDecimal("0.001")),"synthetic-key-001");legacy.receive(ID);verify(sql).call(eq("sp_transfer_start"),any(Object[].class));verify(sql).call(eq("sp_transfer_receive"),any(Object[].class));verify(access,times(3)).branch(OTHER);verifyNoInteractions(f.executor);}
 @Test void allSevenSelectedOperationsCanRunWithoutAnyLegacySql(){actor("ALM");service.lots();service.transfers();service.lot(lotInput());service.move(moveInput("RECEIVE",new BigDecimal("0.001")),"synthetic-key-001");service.transfer(transferInput(new BigDecimal("0.001")),"synthetic-key-002");service.receive(ID);actor("FAR");service.prescriptions();assertEquals(7,f.calls.size());assertEquals(7,new HashSet<>(f.calls).size());verify(access,never()).branch(anyString());verifyNoInteractions(sql);}
 @Test void receiveIdempotenceIsExplicitlyModeledWithoutStockOrAuditAssertions(){actor("ALM");var row=transfer();var effects=new java.util.concurrent.atomic.AtomicInteger();doAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(SqlServerProcedure.INVENTORY_TRANSFER_RECEIVE,inv.getArgument(0));if(row.get("status").equals("IN_TRANSIT")){effects.incrementAndGet();row.put("status","RECEIVED");row.put("receivedAt",DATE);}return new SqlServerExecutor.Result(List.of(List.of(row)),List.of());}).when(f.executor).execute(any(),any(),any(Object[].class));var first=service.receive(ID);var replay=service.receive(ID);assertEquals(first,replay);assertEquals(1,effects.get());verify(f.executor,times(2)).execute(eq(SqlServerProcedure.INVENTORY_TRANSFER_RECEIVE),any(),eq(ID));verifyNoInteractions(sql);}
 @Test void transferReceiveAuthHostAndWriteGateStopBeforeInputOrExecutor(){for(String role:List.of("FAR","AUD","PRO","PAC","SAD","SOP")){actor(role);assertEquals(403,assertThrows(ApiException.class,()->service.transfer(transferInput(BigDecimal.ONE),"synthetic-key-001")).status);assertEquals(403,assertThrows(ApiException.class,()->service.receive(ID)).status);}actor("ALM");f.request.setAttribute("health.actor","forged");assertEquals(403,assertThrows(ApiException.class,()->service.receive(ID)).status);actor("ALM");doThrow(new ApiException(403,"SUSPENDED","Safe")).when(access).write("INVENTORY","ALM");assertEquals("SUSPENDED",assertThrows(ApiException.class,()->service.transfer(null,null)).code);assertEquals("SUSPENDED",assertThrows(ApiException.class,()->service.receive("bad")).code);verifyNoInteractions(f.executor,sql);}
 @Test void transferReplayReceivedIsPreservedAndConflictDoesNotRetry(){actor("ALM");var p=transferInput(new BigDecimal("0.001"));var row=transfer();row.put("lotId",p.lotId());row.put("status","RECEIVED");row.put("receivedAt",DATE);row.put("requestHash",Checks.hash(f.mapper.writeValueAsString(p)));f.results.add(new SqlServerExecutor.Result(List.of(List.of(row)),List.of()));var output=(Map<?,?>)service.transfer(p,"synthetic-key-001");assertEquals(ID,output.get("id"));assertEquals("RECEIVED",output.get("status"));assertEquals(DATE,output.get("receivedAt"));doThrow(new RuntimeException(new java.sql.SQLException("private transfer conflict canary",null,51003))).when(f.executor).execute(eq(SqlServerProcedure.INVENTORY_TRANSFER_START),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->service.transfer(p,"synthetic-key-001"));assertEquals(409,e.status);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));verify(f.executor,times(2)).execute(eq(SqlServerProcedure.INVENTORY_TRANSFER_START),any(),any(Object[].class));verifyNoInteractions(sql);}
 @Test void transferReceiveCommitMappingAndOuterRollbackDoNotReturnPartialSuccess(){actor("ALM");f.manager.failCommit=true;assertEquals(500,assertThrows(ApiException.class,()->service.transfer(transferInput(BigDecimal.ONE),"synthetic-key-001")).status);f.results.add(new SqlServerExecutor.Result(List.of(List.of(transfer())),List.of()));assertEquals(500,assertThrows(ApiException.class,()->service.receive(ID)).status);assertEquals("rollback",f.manager.events.getLast());assertThrows(RuntimeException.class,()->f.manager.outer(()->{service.receive(ID);throw new RuntimeException("cancel");}));assertEquals("rollback",f.manager.events.getLast());assertSame(f.actor,f.request.getAttribute("health.actor"));verifyNoInteractions(sql);}

}
